        return (False, None)
    if not (isinstance(p_mod, int) and p_mod >= 2):
        return (False, None)
    if not (isinstance(q_mod, int) and q_mod >= 2):
        return (False, None)
    if not (isinstance(s_shift, int) and 0 <= s_shift < p_mod):
        return (False, None)
    if not (isinstance(t_shift, int) and 0 <= t_shift < q_mod):
        return (False, None)
    if not (isinstance(lambda_den, int) and lambda_den >= 2):
        return (False, None)
    if not (isinstance(mu_den, int) and mu_den >= 2):
        return (False, None)
    if not (0 < len(a_residues) < p_mod):
        return (False, None)
    if not (0 < len(b_residues) < q_mod):
        return (False, None)
    if any((not isinstance(r, int) or r < 0 or r >= p_mod) for r in a_residues):
        return (False, None)
    if any((not isinstance(r, int) or r < 0 or r >= q_mod) for r in b_residues):
        return (False, None)
    if not (isinstance(scale, int) and scale > 0):
        return (False, None)

    # Build the set of breakpoints where the floor conditions can change
    points = set()
    points.add(Fraction(0, 1))
    points.add(Fraction(1, 1))
    s_frac = Fraction(s_shift, p_mod)
    t_frac = Fraction(t_shift, q_mod)

    for n in range(1, n_max + 1):
        # Breakpoints for floor(n x + s/p)
        # They occur at x = (k - s/p)/n with k = 1..n, clamped to [0,1]
        for k in range(1, n + 1):
            x = (Fraction(k, 1) - s_frac) / n
            if Fraction(0, 1) < x < Fraction(1, 1):
                points.add(x)
        # Breakpoints for floor(2 n x + t/q)
        for k in range(1, 2 * n + 1):
            x = (Fraction(k, 1) - t_frac) / (2 * n)
            if Fraction(0, 1) < x < Fraction(1, 1):
                points.add(x)

    # Sort points and evaluate F(x) on midpoints of intervals
    pts = sorted(points)
    if len(pts) < 2:
        return (False, None)

    # Precompute weights as Fractions to ensure exact arithmetic
    lam_w = [Fraction(0, 1)] * (n_max + 1)
    mu_w = [Fraction(0, 1)] * (n_max + 1)
    for n in range(1, n_max + 1):
        lam_w[n] = Fraction(1, lambda_den ** n)
        mu_w[n] = Fraction(1, mu_den ** n)

    def F_at(x_frac):
        # Compute F(x_frac) exactly
        p = x_frac.numerator
        q = x_frac.denominator
        # Denominators for floor computations
        denom1 = q * p_mod
        denom2 = q * q_mod
        total = Fraction(0, 1)
        for n in range(1, n_max + 1):
            # floor(n x + s/p)
            y1_num = n * p * p_mod + s_shift * q
            y1 = y1_num // denom1
            if (y1 % p_mod) in a_residues:
                total += lam_w[n]
            # floor(2n x + t/q)
            y2_num = 2 * n * p * q_mod + t_shift * q
            y2 = y2_num // denom2
            if (y2 % q_mod) in b_residues:
                total += mu_w[n]
        return total

    L_min = None
    # Evaluate on midpoints of each consecutive pair
    for i in range(len(pts) - 1):
        mid = (pts[i] + pts[i + 1]) / 2
        val = F_at(mid)
        if L_min is None or val < L_min:
            L_min = val
    if L_min is None:
        return (False, None)

    # Scale and floor to get the answer
    scaled = L_min * scale
    # floor for Fraction
    ans = scaled.numerator // scaled.denominator
    return True, int(ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

